/* eslint-disable max-lines -- generated: base64 font payloads. */
/**
 * Noto Kufi Arabic (RSG brand Arabic typeface), Arabic-subset WOFF2, 400 and
 * 700. Imported lazily by TravelHub.tsx only when the RTL feature flag is on
 * (its own webpack chunk), so Latin-only visitors never download it.
 * Sources: src/common/styles/fonts/noto-kufi-arabic-{400,700}.woff2 (from
 * the brand NotoKufiArabic-*.ttf). Licence: SIL OFL 1.1 - THIRD-PARTY-NOTICES.md.
 */
const STYLE_ID = 'th-font-noto-kufi-arabic';
const RANGE = 'U+0600-06FF, U+0750-077F, U+FB50-FDFF, U+FE70-FEFF, U+200C-200F';
const FACES: ReadonlyArray<[number, string]> = [
  [400, ''],
  [700, '']
];

/** Adds the Arabic @font-face rules once. The font stacks already list 'Noto Kufi Arabic'. */
export function loadArabicFont(): void {
  if (typeof document === 'undefined' || document.getElementById(STYLE_ID) !== null) {
    return;
  }
  const style = document.createElement('style');
  style.id = STYLE_ID;
  style.textContent = FACES.map(
    ([weight, data]) =>
      `@font-face{font-family:'Noto Kufi Arabic';font-style:normal;font-weight:${String(weight)};font-display:swap;unicode-range:${RANGE};src:url('data:font/woff2;base64,${data}') format('woff2');}`
  ).join('');
  document.head.appendChild(style);
}
